Archive Submissions As JSON.code:
// Archive today's form submissions as a JSON blob.
uploadBlob(
  // 1) Blob name; slashes act as virtual folders.
  `submissions/${new Date().toISOString().slice(0, 10)}.json`,
  // 2) Content; objects are JSON-stringified for you.
  $.data.submissions,
  // 3) Azure BlockBlobUploadOptions.
  { blobHTTPHeaders: { blobContentType: 'application/json' } },
  // 4) Adaptor options.
  { createContainer: true }
);

Upload CSV Export.code:
// Upload a monthly indicators CSV for the BI team.
uploadBlob(
  `exports/indicators-${$.data.period}.csv`,
  $.data.csv, // a CSV string built in an earlier step
  { blobHTTPHeaders: { blobContentType: 'text/csv' } },
  { overwrite: true } // replace the file if this period is re-run
);

Upload To A Specific Container.code:
// Write a payment reconciliation file to the 'finance' container.
uploadBlob(
  `reconciliation/${$.data.batchId}.json`,
  {
    batchId: $.data.batchId,
    totalPaid: $.data.totalPaid,
    failedPayments: $.data.failed,
  },
  { blobHTTPHeaders: { blobContentType: 'application/json' } },
  {
    containerName: 'finance', // overrides state.configuration.containerName
    overwrite: true,
  }
);

Upload One Blob Per Record.code:
// Store each beneficiary record as its own JSON file.
each(
  $.data.beneficiaries,
  uploadBlob(
    // Inside each(), $.data is the current record.
    `beneficiaries/${$.data.id}.json`,
    $.data,
    { blobHTTPHeaders: { blobContentType: 'application/json' } },
    { overwrite: true }
  )
);

Download JSON Lookup Table.code:
// Download a facility mapping table and parse it as JSON.
// The result is in state.data.content.
downloadBlob('config/facility-mapping.json', {
  downloadAs: 'json', // or 'string' (default)
});

Download File As Text.code:
// Download a CSV dropped by a partner system.
downloadBlob(`incoming/${$.data.fileName}`, {
  downloadAs: 'string',
  containerName: 'partner-uploads', // optional; defaults to the credential's container
});

Get Blob Properties.code:
// Check when the latest export was last written.
// The result is in state.data.properties (lastModified, contentLength, etc.).
getBlobProperties('exports/latest.csv');
